#[inline]
fn destack_display_window_open_replay(
    context: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut resource::WindowHandle,
    options: WindowOptions,
) -> RuntimeResult<()> {
    let _ = &options;

    context.replay().run_binding_with_policy(
        DISPLAY_WINDOW_OPEN,
        context.replay_payload_for(DISPLAY_WINDOW_OPEN)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_display_window_open(context, out, options)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_display_window_open(context, out, options)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value = unsafe {
                    if out.is_null() {
                        return Err(RuntimeError::from(PlatformError::null_pointer("out")).boxed());
                    }
                    *out
                };
                let result_recorded = result_value;
                let payload = DisplayWindowOpenReplay {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(PlatformError::from(error.as_ref()));
                    DisplayWindowOpenReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native = value;
                    unsafe {
                        std::ptr::write(out, value_native);
                    }
                    Ok(())
                }
                Err(error) => Err(RuntimeError::from(error).boxed()),
            }
        },
    )
}

