#[inline]
fn destack_display_window_state_replay(
    context: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut WindowState,
    window: resource::WindowHandle,
) -> RuntimeResult<()> {
    let _ = &window;

    context.replay().run_binding_with_policy(
        DISPLAY_WINDOW_STATE,
        context.replay_payload_for(DISPLAY_WINDOW_STATE)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_display_window_state(context, out, window)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_display_window_state(context, out, window)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value = unsafe {
                    if out.is_null() {
                        return Err(RuntimeError::from(PlatformError::null_pointer("out")).boxed());
                    }
                    *out
                };
                let result_recorded_position_x = result_value.position.x;
                let result_recorded_position_y = result_value.position.y;
                let result_recorded_position = WindowPosition {
                    x: result_recorded_position_x,
                    y: result_recorded_position_y,
                };
                let result_recorded_size_logical_width = result_value.size_logical.width;
                let result_recorded_size_logical_height = result_value.size_logical.height;
                let result_recorded_size_logical = WindowLogicalSize {
                    width: result_recorded_size_logical_width,
                    height: result_recorded_size_logical_height,
                };
                let result_recorded_size_physical_width = result_value.size_physical.width;
                let result_recorded_size_physical_height = result_value.size_physical.height;
                let result_recorded_size_physical = WindowPhysicalSize {
                    width: result_recorded_size_physical_width,
                    height: result_recorded_size_physical_height,
                };
                let result_recorded_scale_factor_milli = result_value.scale_factor_milli;
                let result_recorded_visibility = result_value.visibility;
                let result_recorded_display = if let Some(value) = result_value.display {
                    let result_recorded_display_inner = value;
                    Some(result_recorded_display_inner)
                } else {
                    None
                };
                let result_recorded_focused = result_value.focused;
                let result_recorded_occluded = result_value.occluded;
                let result_recorded_theme = result_value.theme;
                let result_recorded_always_on_top = result_value.always_on_top;
                let result_recorded = WindowState {
                    position: result_recorded_position,
                    size_logical: result_recorded_size_logical,
                    size_physical: result_recorded_size_physical,
                    scale_factor_milli: result_recorded_scale_factor_milli,
                    visibility: result_recorded_visibility,
                    display: result_recorded_display,
                    focused: result_recorded_focused,
                    occluded: result_recorded_occluded,
                    theme: result_recorded_theme,
                    always_on_top: result_recorded_always_on_top,
                };
                let payload = DisplayWindowStateReplay {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(PlatformError::from(error.as_ref()));
                    DisplayWindowStateReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native_position_x = value.position.x;
                    let value_native_position_y = value.position.y;
                    let value_native_position = WindowPosition {
                        x: value_native_position_x,
                        y: value_native_position_y,
                    };
                    let value_native_size_logical_width = value.size_logical.width;
                    let value_native_size_logical_height = value.size_logical.height;
                    let value_native_size_logical = WindowLogicalSize {
                        width: value_native_size_logical_width,
                        height: value_native_size_logical_height,
                    };
                    let value_native_size_physical_width = value.size_physical.width;
                    let value_native_size_physical_height = value.size_physical.height;
                    let value_native_size_physical = WindowPhysicalSize {
                        width: value_native_size_physical_width,
                        height: value_native_size_physical_height,
                    };
                    let value_native_scale_factor_milli = value.scale_factor_milli;
                    let value_native_visibility = value.visibility;
                    let value_native_display = if let Some(value) = value.display {
                        let value_native_display_inner = value;
                        Some(value_native_display_inner)
                    } else {
                        None
                    };
                    let value_native_focused = value.focused;
                    let value_native_occluded = value.occluded;
                    let value_native_theme = value.theme;
                    let value_native_always_on_top = value.always_on_top;
                    let value_native = WindowState {
                        position: value_native_position,
                        size_logical: value_native_size_logical,
                        size_physical: value_native_size_physical,
                        scale_factor_milli: value_native_scale_factor_milli,
                        visibility: value_native_visibility,
                        display: value_native_display,
                        focused: value_native_focused,
                        occluded: value_native_occluded,
                        theme: value_native_theme,
                        always_on_top: value_native_always_on_top,
                    };
                    unsafe {
                        std::ptr::write(out, value_native);
                    }
                    Ok(())
                }
                Err(error) => Err(RuntimeError::from(error).boxed()),
            }
        },
    )
}

