#[inline]
fn destack_display_window_state_vm_replay(
    runtime: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    window: resource::WindowHandle,
) -> RuntimeResult<vm::Value> {
    let result = runtime.replay().run_binding_with_context_policy(
        DISPLAY_WINDOW_STATE,
        runtime.replay_payload_for(DISPLAY_WINDOW_STATE)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_display_window_state(runtime, context, window)
            }
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_display_window_state(runtime, context, window)
            }
        },
        |context, result| {
            let _ = &context;
            if let Ok(value) = result {
                let result_value: WindowStateVm = value.clone();
                let result_recorded_position_x = result_value.position.x;
                let result_recorded_position_y = result_value.position.y;
                let result_recorded_position = WindowPosition {
                    x: result_recorded_position_x,
                    y: result_recorded_position_y,
                };
                let result_recorded_size_logical_width = result_value.size_logical.width;
                let result_recorded_size_logical_height = result_value.size_logical.height;
                let result_recorded_size_logical = WindowLogicalSize {
                    width: result_recorded_size_logical_width,
                    height: result_recorded_size_logical_height,
                };
                let result_recorded_size_physical_width = result_value.size_physical.width;
                let result_recorded_size_physical_height = result_value.size_physical.height;
                let result_recorded_size_physical = WindowPhysicalSize {
                    width: result_recorded_size_physical_width,
                    height: result_recorded_size_physical_height,
                };
                let result_recorded_scale_factor_milli = result_value.scale_factor_milli;
                let result_recorded_visibility = result_value.visibility;
                let result_recorded_display = if let Some(value) = result_value.display {
                    let result_recorded_display_inner = value;
                    Some(result_recorded_display_inner)
                } else {
                    None
                };
                let result_recorded_focused = result_value.focused;
                let result_recorded_occluded = result_value.occluded;
                let result_recorded_theme = result_value.theme;
                let result_recorded_always_on_top = result_value.always_on_top;
                let result_recorded = WindowState {
                    position: result_recorded_position,
                    size_logical: result_recorded_size_logical,
                    size_physical: result_recorded_size_physical,
                    scale_factor_milli: result_recorded_scale_factor_milli,
                    visibility: result_recorded_visibility,
                    display: result_recorded_display,
                    focused: result_recorded_focused,
                    occluded: result_recorded_occluded,
                    theme: result_recorded_theme,
                    always_on_top: result_recorded_always_on_top,
                };
                let payload = DisplayWindowStateReplay {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(PlatformError::from(error.as_ref()));
                    DisplayWindowStateReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let _ = &context;
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result_position_x = value.position.x;
                    let vm_result_position_y = value.position.y;
                    let vm_result_position = WindowPositionVm {
                        x: vm_result_position_x,
                        y: vm_result_position_y,
                    };
                    let vm_result_size_logical_width = value.size_logical.width;
                    let vm_result_size_logical_height = value.size_logical.height;
                    let vm_result_size_logical = WindowLogicalSizeVm {
                        width: vm_result_size_logical_width,
                        height: vm_result_size_logical_height,
                    };
                    let vm_result_size_physical_width = value.size_physical.width;
                    let vm_result_size_physical_height = value.size_physical.height;
                    let vm_result_size_physical = WindowPhysicalSizeVm {
                        width: vm_result_size_physical_width,
                        height: vm_result_size_physical_height,
                    };
                    let vm_result_scale_factor_milli = value.scale_factor_milli;
                    let vm_result_visibility = value.visibility;
                    let vm_result_display = if let Some(value) = value.display {
                        let vm_result_display_inner = value;
                        Some(vm_result_display_inner)
                    } else {
                        None
                    };
                    let vm_result_focused = value.focused;
                    let vm_result_occluded = value.occluded;
                    let vm_result_theme = value.theme;
                    let vm_result_always_on_top = value.always_on_top;
                    let vm_result = WindowStateVm {
                        position: vm_result_position,
                        size_logical: vm_result_size_logical,
                        size_physical: vm_result_size_physical,
                        scale_factor_milli: vm_result_scale_factor_milli,
                        visibility: vm_result_visibility,
                        display: vm_result_display,
                        focused: vm_result_focused,
                        occluded: vm_result_occluded,
                        theme: vm_result_theme,
                        always_on_top: vm_result_always_on_top,
                    };
                    Ok(vm_result)
                }
                Err(error) => Err(RuntimeError::from(error).boxed()),
            }
        },
    );
    let result = encode_destack_display_window_state_result(context, result)?;
    Ok(result)
}

